// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: loadTopBarModule.
async function loadTopBarModule() {
  try {
    const container = document.getElementById('topbar-container');
    if (container) {
      const res = await fetch('topbar.html?t=' + Date.now());
      if (res.ok) {
        const html = await res.text();
        container.innerHTML = html;
        setupTopBarEvents();
        const curLang = window.currentLanguage || localStorage.getItem('siteLang') || 'hu';
        if (typeof window.applyLanguageToUI === 'function') {
          window.applyLanguageToUI(curLang);
        }
      }
    } else {
      setupTopBarEvents();
    }
  } catch (e) {
    console.error('Hiba a TopBar betöltésekor:', e);
  } finally {
    window.updateTopBarPlayerName();
  }
}
// === [#TUTOR.04.07.00] END ===

