// === [#TUTOR.04.1B.00] START | name: applyHartyaTemplateToMesh | lines: ~19 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: applyHartyaTemplateToMesh.
function applyHartyaTemplateToMesh(group) {
  if (!hartyaTemplate || !group) return;
  if (group.userData && group.userData.hasModel && group.getObjectByName('membraneModel')) return;

  // Eltávolítjuk az ideiglenes fallback gömböt
  const toRemove = [];
  group.children.forEach(child => {
    if (child.name === 'membranePlaceholder' || (child.isMesh && child.name !== 'membraneModel')) {
      toRemove.push(child);
    }
  });
  toRemove.forEach(child => group.remove(child));

  const hartyaModel = hartyaTemplate.clone(true);
  hartyaModel.name = 'membraneModel';
  hartyaModel.position.set(0, 0.5, 0);
  group.add(hartyaModel);
  group.userData.hasModel = true;
}
// === [#TUTOR.04.1B.00] END ===

// === [#TUTOR.04.1C.00] START | name: createMembraneMesh | lines: ~36 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: createMembraneMesh.
function createMembraneMesh(x, y, z) {
  const group = new THREE.Group();
  group.position.set(x, y, z);

  if (hartyaTemplate) {
    const hartyaModel = hartyaTemplate.clone(true);
    hartyaModel.name = 'membraneModel';
    hartyaModel.position.set(0, 0.5, 0);
    group.add(hartyaModel);
    group.userData.hasModel = true;
  } else {
    const coreGeo = new THREE.SphereGeometry(0.7, 16, 16);
    const coreMat = new THREE.MeshBasicMaterial({ color: 0xffc800, transparent: true, opacity: 0.40, depthWrite: false });
    const coreMesh = new THREE.Mesh(coreGeo, coreMat);
    coreMesh.name = 'membranePlaceholder';
    coreMesh.position.y = 0.5;
    group.add(coreMesh);
    group.userData.hasModel = false;
  }

  // Szórt fény (diffuse light): felülről sugárzó, lágy esésű arany fényforrás
  const candleLight = new THREE.PointLight(0xffd54f, 2.8, 28, 1.5);
  candleLight.position.set(0, 1.2, 0);
  group.add(candleLight);

  group.userData = {
    ...group.userData,
    isMembrane: true,
    collected: true,
    inUse: false,
    baseY: y,
    light: candleLight
  };

  return group;
}
// === [#TUTOR.04.1C.00] END ===

// === [#TUTOR.04.1D.00] START | name: initMembranePool | lines: ~19 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: initMembranePool.
window.initMembranePool = function () {
  window.membranePool = window.membranePool || [];

  // Ha a hartyaTemplate már elérhető, az összes korábbi pool elemet és aktív hártyát azonnal frissítjük az arany 3D modellre!
  if (hartyaTemplate) {
    window.membranePool.forEach(m => applyHartyaTemplateToMesh(m));
    if (window.activeMembranes && window.activeMembranes.length > 0) {
      window.activeMembranes.forEach(m => applyHartyaTemplateToMesh(m));
    }
  }

  while (window.membranePool.length < MEMBRANE_POOL_SIZE) {
    const m = createMembraneMesh(0, -999, 0);
    m.visible = false;
    if (m.userData.light) m.userData.light.intensity = 0;
    scene.add(m);
    window.membranePool.push(m);
  }
};
// === [#TUTOR.04.1D.00] END ===

// === [#TUTOR.04.1E.00] START | name: getPooledMembrane | lines: ~17 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: getPooledMembrane.
function getPooledMembrane() {
  window.initMembranePool();
  for (let i = 0; i < window.membranePool.length; i++) {
    const m = window.membranePool[i];
    if (!m.userData.inUse) {
      if (hartyaTemplate && !m.userData.hasModel) {
        applyHartyaTemplateToMesh(m);
      }
      return m;
    }
  }
  const newM = createMembraneMesh(0, -999, 0);
  newM.visible = false;
  scene.add(newM);
  window.membranePool.push(newM);
  return newM;
}
window.getPooledMembrane = getPooledMembrane;
// === [#TUTOR.04.1E.00] END ===

// === [#TUTOR.04.1F.00] START | name: loadMembraneModel | lines: ~55 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: loadMembraneModel.
function loadMembraneModel() {
  const modelUrl = window.getAssetUrl('models/hartya_golden_membrane.glb');
  new GLTFLoader().load(modelUrl, function (gltf) {
    hartyaTemplate = gltf.scene;
    hartyaTemplate.scale.set(3.0, 3.0, 3.0);
    hartyaTemplate.traverse(c => {
      if (c.isMesh) {
        if (c.material) {
          c.material.side = THREE.DoubleSide;
          // Ha nincs beállítva fényes textúra, meleg arany fényt adunk
          if (c.material.color) {
            c.material.color.setHex(0xffd700);
          }
          if (c.material.emissive) {
            c.material.emissive.setHex(0xff9900);
            c.material.emissiveIntensity = 0.5;
          }
        }
      }
    });

    // Frissítjük a poolt és az aktív hártyákat is a valódi 3D arany modellel!
    if (window.membranePool) {
      window.membranePool.forEach(m => applyHartyaTemplateToMesh(m));
    }
    if (window.activeMembranes) {
      window.activeMembranes.forEach(m => applyHartyaTemplateToMesh(m));
    }
    window.initMembranePool();

    const isLoadMode = window.location.search.includes('load=1');
    if (isLoadMode) {
      if (typeof window.loadFullGameState === 'function') {
        window.loadFullGameState();
      }
    } else if (window.isFishingMode) {
      if (typeof window.spawnFishingMembranes === 'function') {
        window.spawnFishingMembranes();
      }
    } else {
      if (typeof window.spawnZeroPointMembrane === 'function') {
        window.spawnZeroPointMembrane();
      }
    }
  }, undefined, function (err) {
    console.warn("hartya_golden_membrane.glb betöltése sikertelen, próbálkozás hartya.glb-vel:", err);
    new GLTFLoader().load(window.getAssetUrl('models/hartya.glb'), function (fallbackGltf) {
      hartyaTemplate = fallbackGltf.scene;
      hartyaTemplate.scale.set(3.0, 3.0, 3.0);
      if (window.membranePool) {
        window.membranePool.forEach(m => applyHartyaTemplateToMesh(m));
      }
      if (window.activeMembranes) {
        window.activeMembranes.forEach(m => applyHartyaTemplateToMesh(m));
      }
      window.initMembranePool();
    });
  });
}
// === [#TUTOR.04.1F.00] END ===
loadMembraneModel();

// --- HÁRTYA SANITIZER ÉS BERAGADÁS-MEGSZÜNTETŐ RUTIN ---
// === [#TUTOR.04.20.00] START | name: sanitizeAndAutoRecoverMembranes | lines: ~38 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: HÁRTYA SANITIZER ÉS BERAGADÁS-MEGSZÜNTETŐ RUTIN ---
window.sanitizeAndAutoRecoverMembranes = function() {
  if (typeof scene === 'undefined' || !scene) return;

  window.activeMembranes = window.activeMembranes || [];

  // 1. Érintéses beragadási ellenőrző (Touch Watchdog):
  if (typeof boat !== 'undefined' && boat && boat.position && window.activeMembranes.length > 0) {
    const bx = boat.position.x;
    const bz = boat.position.z;
    const _wPos = new THREE.Vector3();

    for (let i = window.activeMembranes.length - 1; i >= 0; i--) {
      const m = window.activeMembranes[i];
      if (!m) continue;
      m.getWorldPosition(_wPos);
      const distSq = (_wPos.x - bx) * (_wPos.x - bx) + (_wPos.z - bz) * (_wPos.z - bz);

      if (distSq < 16.0) {
        m.userData.touchStuckTime = (m.userData.touchStuckTime || 0) + 1;
        if (m.userData.touchStuckTime > 2) {
          console.warn("Beragadt/felvehetetlen hártya észlelve -> Vissza a poolba és újragenerálás!");
          m.userData.collected = true;
          m.userData.inUse = false;
          m.visible = false;
          if (m.userData.light) m.userData.light.intensity = 0;
          m.position.set(0, -999, 0);
          window.activeMembranes.splice(i, 1);

          if (typeof window.spawnHartyaWave === 'function' && window.storedMembranes < 30) {
            window.spawnHartyaWave(1, 'boat');
          }
        }
      } else {
        m.userData.touchStuckTime = 0;
      }
    }
  }
};
// === [#TUTOR.04.20.00] END ===

// === [#TUTOR.04.21.00] START | name: spawnZeroPointMembrane | lines: ~25 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: spawnZeroPointMembrane.
window.spawnZeroPointMembrane = function () {
  window.initMembranePool();

  if (window.activeMembranes) {
    window.activeMembranes.forEach(m => {
      m.visible = false;
      if (m.userData.light) m.userData.light.intensity = 0;
      m.userData.inUse = false;
      m.userData.collected = true;
      m.position.set(0, -999, 0);
    });
  }
  window.activeMembranes = [];

  const firstMembrane = getPooledMembrane();
  firstMembrane.position.set(0, 0.1, 0);
  firstMembrane.userData.baseY = 0.1;
  firstMembrane.userData.collected = false;
  firstMembrane.userData.inUse = true;
  firstMembrane.visible = true;
  if (firstMembrane.userData.light) firstMembrane.userData.light.intensity = 1.2;

  window.activeMembranes.push(firstMembrane);
  window.totalSpawnedCount = 1;
};
