addEventListener('keydown', (e) => {
  // Tuner panel és beviteli mezők esetén ne léptessen a Space
  if (e.target && (e.target.closest('#textbox-tuner-panel') || e.target.closest('#btn-toggle-textbox-tuner') || e.target.tagName === 'SELECT')) return;

  const isTextInput = e.target && (
    e.target.tagName === 'TEXTAREA' || 
    (e.target.tagName === 'INPUT' && !['range', 'button', 'checkbox', 'radio', 'submit'].includes((e.target.type || '').toLowerCase()))
  );
  if (isTextInput) return;

  // A felhasználó kifejezett szabálya: KIZÁRÓLAG a Space billentyű léptet (az Enter nem léptethet)!
  const isSpace = e.code === 'Space' || e.key === ' ' || e.keyCode === 32;
  if (!isSpace) return;

  e.preventDefault();

  // Ha a hangoló nyitva van és aktív egy monológ vagy irányító panel, a Space a következő dialógusra léptet
  const tunerPanel = document.getElementById('textbox-tuner-panel');
  const ingameContainer = document.getElementById('zozo-ingame-monolog-container');
  const welcomeOverlay = document.getElementById('zozo-welcome-overlay');
  const popupToast = document.getElementById('ingame-popup-toast');
  const eogDialog = document.getElementById('eog-compact-dialog');

  // Normál Space léptetési lánc: Welcome boxok → In-Game Monológ / Irányító Panel → PopUpok → EoG
  if (welcomeOverlay && welcomeOverlay.style.display !== 'none') {
    window.advanceZozoWelcome(e);
  } else if (ingameContainer && ingameContainer.style.display !== 'none') {
    window.advanceInGameMonolog(e);
  } else if (popupToast && popupToast.style.display !== 'none') {
    window.dismissActivePopup(e);
  } else if (eogDialog && eogDialog.style.display !== 'none') {
    if (typeof window.closeEogDialog === 'function') {
      window.closeEogDialog();
    }
  }
});

addEventListener('click', (e) => {
  // A KILÉPÉS GOMB & A KILÉPÉSI ABLAK GOMBJAI BÁRMIKOR (még a Welcome boxok alatt is) MŰKÖDNEK!
  if (e.target.closest('#btn-tb-anchor')) {
    if (typeof window.showBayExitDialog === 'function') {
      window.showBayExitDialog(true);
    }
    return;
  }

  if (e.target.closest('#btn-tb-exit')) {
    const exitOverlay = document.getElementById('exit-confirm-overlay');
    if (exitOverlay) {
      exitOverlay.style.display = 'flex';
      window.isCutscenePlaying = true;
    }
    return;
  }

  if (e.target.closest('#btn-exit-no')) {
    const exitOverlay = document.getElementById('exit-confirm-overlay');
    if (exitOverlay) {
      exitOverlay.style.display = 'none';
      window.isCutscenePlaying = false;
    }
    return;
  }

  if (e.target.closest('#btn-exit-yes')) {
    // ----------------------------------------------------
    // KILÉPÉS: VESSZENEK A HÁRTYÁK
    // ----------------------------------------------------
    const exitOverlay = document.getElementById('exit-confirm-overlay');
    if (exitOverlay) exitOverlay.style.display = 'none';

    // A hajón levő hártyák elvesznek
    window.carriedMembranes = 0;
    if (typeof window.updateTopBarCounts === 'function') window.updateTopBarCounts();

    // A játékos adatlapjára felíródnak a bázison tárolt (stored) hártyák
    if (window.parent && window.parent !== window && typeof window.parent.callBackend === 'function') {
      if (window.storedMembranes > 0) {
        window.parent.callBackend('saveHartyaScore', [window.storedMembranes]);
      }
      window.parent.callBackend('saveBoatDurability', [window.boatDurability || 10]);
    }

    if (window.parent && window.parent !== window) {
      window.parent.postMessage({
        source: 'threejs-minigame',
        status: 'COMPLETED',
        gameType: 'FISHING',
        exitType: 'QUIT_DISCARD',
        score: window.storedMembranes || 0
      }, '*');
    } else {
      const targetUrl = 'https://krystohans.github.io/ebookpirates_site/';
      if (window.top && window.top !== window) window.top.location.href = targetUrl;
      else window.location.href = targetUrl;
    }
    return;
  }

  // Ha a fejlesztői hangoló panelre vagy annak gombjaira kattint a felhasználó, ne léptessük el a dialógust!
  if (e.target.closest('#textbox-tuner-panel') || e.target.closest('#btn-toggle-textbox-tuner')) {
    return;
  }

  const welcomeOverlay = document.getElementById('zozo-welcome-overlay');
  const ingameContainer = document.getElementById('zozo-ingame-monolog-container');
  const popupToast = document.getElementById('ingame-popup-toast');

  // Felhasználói szabály: KIZÁRÓLAG a Space billentyű léptetheti a monológokat/párbeszédeket!
  // Egérkattintásos léptetés szigorúan tiltva van a játékos kérésére.
});

// === [#TUTOR.04.32.00] START | name: resetAirshipChase | lines: ~10 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: resetAirshipChase.
window.resetAirshipChase = function () {
  window.airshipChaseState = 'RETREAT';
  window.airshipChaseCooldown = 20.0;
  window.monologState.airshipCaughtPlayer = false;
  window.airshipAbductionActive = false;
  if (window.airshipLadderMesh) window.airshipLadderMesh.visible = false;
  if (window.foundZeppelin) {
    window.airshipTargetRotY = window.foundZeppelin.rotation.y;
  }
};
// === [#TUTOR.04.32.00] END ===

const clock = new THREE.Clock();
resize();

const TARGET_FPS = 60;
const FRAME_MIN_MS = 1000 / TARGET_FPS; // 16.667ms
let _lastFrameTime = 0;

// === [#TUTOR.04.33.00] START | name: frame | lines: ~1 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: frame.
function frame(now) {
// === [#TUTOR.04.33.00] END ===
  requestAnimationFrame(frame);

  // 60 FPS korlát: ha túl hamar hívódik (pl. 144Hz monitoron), kihagyjuk a frame-et
  if (now - _lastFrameTime < FRAME_MIN_MS) return;
  _lastFrameTime = now;

  // A videó lejátszása alatt leállítjuk a teljes 3D renderelést és fizikai számításokat,
  // így a GPU és CPU 100%-ban a hardveres videó dekódolásra tud koncentrálni, megszüntetve a laggot!
  if (window.eogState === 'VIDEO') {
    return;
  }
  if (window.isPaused) {
    return;
  }

  const rawDt = clock.getDelta();

  const dt = window.isCutscenePlaying ? 0 : Math.min(rawDt, 0.05);
  const cutsceneDt = Math.min(rawDt, 0.05);
  const t = clock.getElapsedTime();
  const coordDiv = document.getElementById('tb-coords') || document.getElementById('debug-coords');
  if (coordDiv && boat && boat.position && typeof boat.position.x === 'number') {
    coordDiv.innerText = `X: ${boat.position.x.toFixed(1)}, Z: ${boat.position.z.toFixed(1)}`;
  }

  const tbDurability = document.getElementById('tb-durability-count');
  if (tbDurability) tbDurability.innerText = window.boatDurability !== undefined ? window.boatDurability : 10;
  const tbCarried = document.getElementById('tb-carried-count');
  if (tbCarried) tbCarried.innerText = window.carriedMembranes || 0;
  const tbStored = document.getElementById('tb-stored-count');
  if (tbStored) tbStored.innerText = window.storedMembranes || 0;


  if (typeof boat !== 'undefined' && boat && boat.position) {
    const distToDock = Math.hypot(boat.position.x - 5, boat.position.z - (-94));
    
    // Ha legalább 25 méterre eltávolodott a dokktól, feljegyezzük, hogy elhagyta a kikötőt
    if (distToDock > 25) {
      window.hasLeftDockAtLeastOnce = true;
    }

    if (window.isFishingMode) {
      // A kikötői állapotot (window.isAtDock) és lerakást kizárólag a kikötői zóna kódja kezeli az 5879. sornál
    }
  }

  // ═══════════════════════════════════════════════════════════════════
  // 🚢 CSATAHAJÓ VADÁSZAT: AZ ÖBÖL SZÁJÁN TÚLI NYÍLT TENGEREN (z >= 1250)
  // ═══════════════════════════════════════════════════════════════════
  if (window.warshipMesh && window.isFishingMode) {
    const warship = window.warshipMesh;
    const tW = t * 0.15; // Járőrözési sebesség
    const centerX = -450, centerZ = 1650; // Az öböl száján (z=1250..1350) messze túl a nyílt tengeren!
    const radiusX = 280, radiusZ = 180;

    // Nyolcas (Lissajous) pálya az öböl száján messze túl a nyílt tengeren
    const nextX = centerX + Math.sin(tW) * radiusX;
    const nextZ = centerZ + Math.sin(2 * tW) * radiusZ;

    const dx = radiusX * Math.cos(tW) * 0.15;
    const dz = radiusZ * 2 * Math.cos(2 * tW) * 0.15;
    const targetAngle = Math.atan2(dx, dz); // Pontosan 180 fokkal megfordítva, hogy előrefelé hajózzon az orrával!

    warship.position.set(nextX, 0, nextZ);
    warship.rotation.y = targetAngle;

    // ═══════════════════════════════════════════════════════════════════
    // 🌊 CSATAHAJÓ MOZGÁSI TERÜLETE = AKTÍV ZÓNA:
    // Ha a csónak rámegy a csatahajó mozgási területére (z >= 1250), elindítja 
    // a 'Halászat Befejezése és Mentés' akciót: Hebok kikötőbe utazó videó (terkeputazas01.mp4)
    // és a fedelzet_oldal aloldal betöltése!
    // ═══════════════════════════════════════════════════════════════════
    if (typeof boat !== 'undefined' && boat && boat.position && boat.position.z >= 1250) {
      if (!window._isExitingFishing) {
        window._isExitingFishing = true;

        // Csónakon lévő hártyák azonnali raktárba helyezése és mentése
        if (window.carriedMembranes > 0) {
          window.storedMembranes = (window.storedMembranes || 0) + window.carriedMembranes;
          window.carriedMembranes = 0;
          if (typeof window.updateTopBarCounts === 'function') window.updateTopBarCounts();
        }

        // Felugró tájékoztató felirat
        const crashOverlay = document.getElementById('crash-overlay');
        if (crashOverlay) {
          const crashSpan = crashOverlay.querySelector('span');
          if (crashSpan) crashSpan.innerText = (typeof window.getOpenSeaText === 'function') ? window.getOpenSeaText() : '⚓ Nyílt tenger: Utazás Hebok kikötőbe...';
          crashOverlay.style.display = 'flex';
          setTimeout(() => { crashOverlay.style.display = 'none'; }, 1200);
        }

        // Halászat Befejezése és Hebok kikötőbe utazás
        window.exitFishingGame && window.exitFishingGame('NORMAL');
      }
    }
  }

  const welcomeOverlayActive = document.getElementById('zozo-welcome-overlay') &&
    document.getElementById('zozo-welcome-overlay').style.display !== 'none';

  // Időszakos sanitizer és beragadt hártya ellenőrzés másodpercenként
  window._lastSanitizeTime = window._lastSanitizeTime || 0;
  if (t - window._lastSanitizeTime > 1.0) {
    window._lastSanitizeTime = t;
    if (typeof window.sanitizeAndAutoRecoverMembranes === 'function') {
      window.sanitizeAndAutoRecoverMembranes();
    }
  }

  // 🌿 Dinamikus távolsági culling kis növényekre / részletekre (350m-en kívül nem terheli a GPU-t, míg a hegyek mindig látszódnak)
  window._lastPropCullTime = window._lastPropCullTime || 0;
  if (t - window._lastPropCullTime > 0.5 && window.smallPropsList && window.smallPropsList.length > 0 && typeof boat !== 'undefined' && boat) {
    window._lastPropCullTime = t;
    const _bx = boat.position.x;
    const _bz = boat.position.z;
    const _propWp = new THREE.Vector3();
    const MAX_PROP_DIST_SQ = 122500; // 350m ^ 2
    for (let _pi = 0; _pi < window.smallPropsList.length; _pi++) {
      const _pMesh = window.smallPropsList[_pi];
      if (!_pMesh) continue;
      _pMesh.getWorldPosition(_propWp);
      const _pdx = _propWp.x - _bx;
      const _pdz = _propWp.z - _bz;
      _pMesh.visible = (_pdx * _pdx + _pdz * _pdz < MAX_PROP_DIST_SQ);
    }
  }

  // 🌟 Viharlámpás lágy lélegző pulzálása a horizonton
  if (window.mainRockLanternBeacon) {
    const _bPulse = 1.0 + Math.sin(t * 2.5) * 0.08;
    window.mainRockLanternBeacon.scale.set(8.0 * _bPulse, 8.0 * _bPulse, 1.0);
  }

  if (window.activeMembranes && window.activeMembranes.length > 0 && !welcomeOverlayActive) {
    const bx = boat.position.x;
    const bz = boat.position.z;
    const _mWorldPos = new THREE.Vector3();

    for (let i = window.activeMembranes.length - 1; i >= 0; i--) {
      try {
        const m = window.activeMembranes[i];
        if (!m || m.userData.collected) continue;

        if (dt > 0) {
          m.position.y = m.userData.baseY + Math.sin(t * 2.2 + i) * 0.12;
          if (m.userData.light) {
            m.userData.light.intensity = 2.5 + Math.sin(t * 3.0 + i) * 0.5;
          }
        }

        m.getWorldPosition(_mWorldPos);
        const dx = _mWorldPos.x - bx;
        const dz = _mWorldPos.z - bz;
        const distSq = dx * dx + dz * dz;

        if (window.membranePickUpCount === 0 && distSq < 1225.0 && !window.monologState.hasSeen[2] && !window.isCutscenePlaying) {
          window.showInGameMonolog(2, 2);
        }

        // A csónak fizikai kiterjedéséhez illeszkedő pontos felvételi hatósugár (r = 3.0m, distSq < 9.0)
        if (distSq < 9.0 && !window.isCutscenePlaying) {
          // 1. LEGELŐSZÖR A HÁRTYA AZONNAL VISSZAÁLL A POOLBA!
          m.userData.collected = true;
          m.userData.inUse = false;
          m.visible = false;
          if (m.userData.light) m.userData.light.intensity = 0;
          m.position.set(0, -999, 0);
          const mIdx = window.activeMembranes.indexOf(m);
          if (mIdx > -1) window.activeMembranes.splice(mIdx, 1);

          // 2. AZONNALI HANGEFFEKT A FELVÉTELI ÉRINTÉS PILLANATÁBAN
          if (typeof window.playPickupSound === 'function') window.playPickupSound();

          if (window.isFishingMode) {
            window.fishingMembranePickupCount = (window.fishingMembranePickupCount || 0) + 1;
            const mCount = window.fishingMembranePickupCount;

            // 3 hártyánként egy kvízkérdés (pl. 3., 6., 9., 12...)
            if (mCount % 3 === 0) {
              if (typeof window.triggerFishingQuiz === 'function') {
                window.triggerFishingQuiz();
              }
            } else {
              // Sima hártyafelvétel kvíz nélkül
              window.carriedMembranes = (window.carriedMembranes || 0) + 1;
              if (typeof window.updateTopBarCounts === 'function') window.updateTopBarCounts();
              if (typeof window.showPopUp === 'function') window.showPopUp(window.getMembranePickupNoQuizText ? window.getMembranePickupNoQuizText() : "Sikeres hártyafelvétel. (+1 a fedélzeten)");
              if (typeof window.changeWindForNextMembrane === 'function') window.changeWindForNextMembrane();
              setTimeout(function () {
                if (typeof window.spawnFishingMembranes === 'function') window.spawnFishingMembranes();
              }, 1200);
            }
            continue;
          }

// === [#TUTOR.04.34.00] START | name: executeMembranePickup | lines: ~62 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: executeMembranePickup.
          const executeMembranePickup = (showDefaultPopup = true) => {
            window.carriedMembranes++;
            window.totalPickedUp++;
            window.membranePickUpCount = (window.membranePickUpCount || 0) + 1;
            const count = window.membranePickUpCount;

            window.gameTimeProgress = Math.min(count / 30.0, 0.90);
            if (typeof window.updateEnvironmentLighting === 'function') window.updateEnvironmentLighting();

// === [#TUTOR.04.35.00] START | name: handleMonologsAndLogic | lines: ~45 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: handleMonologsAndLogic.
            const handleMonologsAndLogic = () => {
              if (count === 1) {
                if (!window.monologState.hasSeen[3]) window.showInGameMonolog(3, 4);
              } 
              else if (count === 2) {
                window.isWindActive = true;
                window.playSoundEffect(window.windStartAudio);
                if (typeof window.changeWindForNextMembrane === 'function') window.changeWindForNextMembrane();
                if (!window.monologState.hasSeen[7]) window.showInGameMonolog(7, 8);
              } 
              else if (count === 3) {
                if (typeof window.changeWindForNextMembrane === 'function') window.changeWindForNextMembrane();
                window.pendingAirshipAscent = false;
                window.airshipAscentStarted = true;
                if (typeof window.playSoundEffect === 'function') window.playSoundEffect(window.airshipAscentAudio);
                window.airshipAscentDone = false;
                window.isCutscenePlaying = true;
                window.airshipTimer = 0;
                window.airshipCutsceneStage = 'ASCEND';
                window.airshipChaseCooldown = 0;
              }
              else if (count === 4) {
                if (typeof window.changeWindForNextMembrane === 'function') window.changeWindForNextMembrane();
                if (!window.monologState.hasSeen[11]) window.showInGameMonolog([11, 12, 13, 14, 15, 16, 17]);
                else if (!window.monologState.hasSeen[15]) window.showInGameMonolog(15, 17);
              }
              else if (count === 5) {
                if (!window.monologState.hasSeen[18]) window.showInGameMonolog(18, 21);
              }
              else if (count === 6) {
                if (!window.monologState.hasSeen[22]) window.showInGameMonolog(22, 23);
              }
              else if (count === 7) {
                if (!window.monologState.hasSeen[24]) window.showInGameMonolog(24, 25);
              }
              else if (count === 8) {
                if (!window.monologState.hasSeen[26]) window.showInGameMonolog(26, 27);
              }
              else if (count === 9) {
                if (!window.monologState.hasSeen[28]) window.showInGameMonolog(28, 28);
              }
              else if (count === 10) {
                if (!window.monologState.hasSeen[29]) window.showInGameMonolog(29, 31);
              }
            };
// === [#TUTOR.04.35.00] END ===

            // A 3. hártyánál azonnal induljon a léghajós cutscene, ne várjon a popupra
            if (count !== 3 && showDefaultPopup) {
              window.showPopUp((window.getMembranePickupNoQuizText ? window.getMembranePickupNoQuizText() : "Sikeres hártyafelvétel. (+1 a fedélzeten)"), handleMonologsAndLogic);
            } else {
              handleMonologsAndLogic();
// === [#TUTOR.04.34.00] END ===
            }
          };

// === [#TUTOR.04.36.00] START | name: executeMembraneMiss | lines: ~12 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: executeMembraneMiss.
          const executeMembraneMiss = () => {
            m.userData.collected = true;
            m.userData.inUse = false;
            m.visible = false;
            if (m.userData.light) m.userData.light.intensity = 0;
            m.position.set(0, -999, 0);
            const mIdx = window.activeMembranes.indexOf(m);
            if (mIdx > -1) window.activeMembranes.splice(mIdx, 1);
            m.userData.isBeingPickedUp = false;

            window.showPopUp((window.gamePopups && window.gamePopups.membrane_bad) || "Ez a hártya most elúszott!");
          };
// === [#TUTOR.04.36.00] END ===

          // 12 hártyánként pontosan 3 alkalommal (3 / 12) indul kvíz
          if (!window._membraneQuizCycle || window._membraneQuizCycle.length === 0) {
            window._membraneQuizCycle = [true, true, true, false, false, false, false, false, false, false, false, false].sort(() => Math.random() - 0.5);
          }
          if (window._membraneQuizCycle.pop() && window.quizManager) {
            window.quizManager.openQuiz('TUTOR_GameInfo', (isCorrect) => {
              if (isCorrect) {
                window.showPopUp((window.getMembraneGoodText ? window.getMembraneGoodText() : "Helyes válasz! Sikeres hártyabegyűjtés (+1 a fedélzeten)."), () => {
                  executeMembranePickup(false);
                });
              } else {
                executeMembraneMiss();
              }
            });
          } else {
            executeMembranePickup(true);
          }
        }
      } catch (err) {
        console.error("Hártya hiba:", err);
      }
    }
  }

  if (window.airshipChaseCooldown > 0) {
    window.airshipChaseCooldown -= cutsceneDt;
    if (window.airshipChaseCooldown <= 0) window.airshipChaseCooldown = 0;
  }

  if (window.airshipAscentStarted && !window.airshipAscentDone && window.foundZeppelin) {
    window.airshipTimer = (window.airshipTimer || 0) + cutsceneDt;
    const zep = window.foundZeppelin;

    if (zep.position.y < 40.0) {
      zep.position.y += cutsceneDt * 25.0;
    } else {
      zep.position.y = 40.0;
    }

    const bayTarget = new THREE.Vector3(-300, 40, 600);
    const dir = new THREE.Vector3().subVectors(bayTarget, zep.position).normalize();
    const targetRotY = Math.atan2(dir.x, dir.z) - Math.PI;
    zep.rotation.y += (targetRotY - zep.rotation.y) * cutsceneDt * 2.0;
    zep.position.add(dir.multiplyScalar(cutsceneDt * 30.0));

    if (window.airshipTimer > 2.2) {
      window.airshipAscentDone = true;
      window.airshipChaseState = 'CHASE';
      window.airshipChaseCooldown = 0;

      if (!window.monologState.hasSeen[9]) {
        window.showInGameMonolog(9, 9, function () {
          window.isCutscenePlaying = false;
        });
      } else {
        window.isCutscenePlaying = false;
      }
    }
  }

  if (window._waitingForPierLeave && window.homePos) {
    const dxP = boat.position.x - window.homePos.x;
    const dzP = boat.position.z - window.homePos.z;
    if (dxP * dxP + dzP * dzP > 2500.0) {
      window._waitingForPierLeave = false;

// === [#TUTOR.04.37.00] START | name: startWind | lines: ~5 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: startWind.
      const startWind = () => {
        window.isWindActive = true;
        window.playSoundEffect(window.windStartAudio);
        if (typeof window.changeWindForNextMembrane === 'function') window.changeWindForNextMembrane();
      };
// === [#TUTOR.04.37.00] END ===

      if (!window.monologState.hasSeen['wind_toast_shown']) {
        window.monologState.hasSeen['wind_toast_shown'] = true;
        window.showInGameMonolog(['wind'], null, startWind);
      } else {
        startWind();
      }
    }
  }

  // ═══════════════════════════════════════════════════════════════════
  // KIKÖTŐI ÉRKEZÉS: 18M-ES ZÓNA (isFishingMode-tól FÜGGETLEN!)
  // Sorrend: 1) boat_fixing → 2) monológok/homepoint/empty_boat
  // ═══════════════════════════════════════════════════════════════════
  if (!window.isCutscenePlaying && !window._dropoffInProgress && window.homePos && typeof boat !== 'undefined' && boat && boat.position) {
    const distHome = Math.hypot(boat.position.x - window.homePos.x, boat.position.z - window.homePos.z);
    if (distHome < 18.0 && !window.isAtDock) {
      window.isAtDock = true;
      window._dropoffInProgress = true;

      // SNAPSHOT: lementjük az érkezéskori állapotot
      const arrivedHP = window.boatDurability;
      const arrivedCarried = window.carriedMembranes || 0;
      const needsFixing = arrivedHP < 10;
      const hasMembranes = arrivedCarried > 0;

      // Ha van hártya, AZONNAL átrakjuk a raktárba
      if (hasMembranes) {
        const previousStored = window.storedMembranes || 0;
        window.storedMembranes = previousStored + arrivedCarried;
        window.carriedMembranes = 0;
        window.firstMembraneDelivered = true;
        window._justDelivered = true;
        if (typeof window.updateTopBarCounts === 'function') window.updateTopBarCounts();
        if (typeof window.playSoundEffect === 'function') window.playSoundEffect(window.homepointTouchAudio);
        if (typeof window.showPopUp === 'function') {
          const curLang = (typeof window.getGameLanguage === 'function')
            ? window.getGameLanguage()
            : (window.currentLanguage || localStorage.getItem('ebook_pirates_language') || localStorage.getItem('siteLang') || 'hu');
          const map = {
            hu: 'Rakomány biztosítva',
            en: 'Cargo secured',
            de: 'Ladung gesichert',
            fr: 'Cargaison sécurisée',
            es: 'Carga asegurada',
            pl: 'Ładunek zabezpieczony',
            ru: 'Груз закреплен'
          };
          window.showPopUp(map[curLang] || map.hu);
        }

        // 30. hártya EoG trigger
        if (window.storedMembranes >= 30 && window.eogState === 'NONE') {
          window.eogState = 'EMPTIED';
          if (window.activeMembranes) {
            window.activeMembranes.forEach(m => {
              m.visible = false;
              if (m.userData.light) m.userData.light.intensity = 0;
              m.userData.inUse = false;
              m.userData.collected = true;
              m.position.set(0, -999, 0);
            });
            window.activeMembranes = [];
          }
          if (!window.chestModel && typeof spawnEogTreasureChest === 'function') {
            spawnEogTreasureChest(scene, EoG_POINT_C);
          }
        }
      }

      // Ha sérült, AZONNAL javítjuk a HP-t
      if (needsFixing) {
        window.boatDurability = 10;
        const tbDur = document.getElementById('tb-durability-count');
        if (tbDur) tbDur.innerText = window.boatDurability;
      }

      // Halászat mód: Zozó monológok és javítási popupok véglegesen törölve, a javítás és lerakás csendben lefut.

      setTimeout(() => { window._dropoffInProgress = false; }, 1200);
      setTimeout(() => { window._justDelivered = false; }, 5000);
    } else if (distHome >= 18.0) {
      window.isAtDock = false;
      if (distHome > 25.0) {
        window.hasLeftDockAtLeastOnce = true;
      }
    }
  }

  // --- LÉGHAJÓ ÜLDÖZÉSI LOGIKA (100 MÉTERES VÉDELMI ZÓNÁVAL - EREDETI TUTORIAL MOTOR) ---
  if (window.airshipAscentDone && window.foundZeppelin && !window.eogTriggerChest && window.eogState !== 'CHEST_FOUND' && window.eogState !== 'CINEMATIC' && window.eogState !== 'CREDITS') {
    const zep = window.foundZeppelin;

    let distBoatToHome = 999.0;
    let distZepToHome = 999.0;
    if (window.homePos) {
      distBoatToHome = Math.hypot(boat.position.x - window.homePos.x, boat.position.z - window.homePos.z);
      distZepToHome = Math.hypot(zep.position.x - window.homePos.x, zep.position.z - window.homePos.z);
    }

    const isInProtectedZone = distBoatToHome < 40.0;

    // Öböl bejárati 15-20 másodperces járőrútvonal (hogy a védett zóna határán soha ne laggoljon a levegőben)
    const AIRSHIP_BAY_WAYPOINTS = [
      new THREE.Vector3(-300, 40, 600), // 1. Nyugati öböl bejárat
      new THREE.Vector3(-100, 42, 850), // 2. Nyílt tengeri kanyar
      new THREE.Vector3(250, 40, 650),  // 3. Keleti öböl bejárat
      new THREE.Vector3(50, 38, 400)    // 4. Belső öbölátjáró
    ];

    if (isInProtectedZone) {
      if (window.airshipChaseState !== 'RETREAT') {
        window.airshipChaseState = 'RETREAT';
        window.airshipChaseCooldown = 6.0;
        window.airshipPatrolIdx = 0;
      }
    }

    if (window.airshipChaseState === 'RETREAT') {
      window.airshipPatrolIdx = (window.airshipPatrolIdx !== undefined) ? window.airshipPatrolIdx : 3;
      let targetPt = AIRSHIP_BAY_WAYPOINTS[window.airshipPatrolIdx] || AIRSHIP_BAY_WAYPOINTS[3];
      const distToPt = zep.position.distanceTo(targetPt);

      // Ha megközelítette az aktuális pontot (35m-re), átvált a következő útvonalpontra
      if (distToPt < 35.0) {
        window.airshipPatrolIdx = (window.airshipPatrolIdx + 1) % AIRSHIP_BAY_WAYPOINTS.length;
        targetPt = AIRSHIP_BAY_WAYPOINTS[window.airshipPatrolIdx];
      }

      const retreatDir = new THREE.Vector3().subVectors(targetPt, zep.position).normalize();
      const targetRetreatRotY = Math.atan2(retreatDir.x, retreatDir.z) - Math.PI;
      zep.rotation.y += (targetRetreatRotY - zep.rotation.y) * cutsceneDt * 2.0;
      zep.position.add(retreatDir.multiplyScalar(cutsceneDt * 18.0));

      if (!isInProtectedZone && window.airshipChaseCooldown <= 0) {
        window.airshipChaseState = 'CHASE';
        window.monologState.airshipCaughtPlayer = false;
      }
    } else {
      if (window.airshipChaseState === 'CHASE' && !window.isCutscenePlaying) {
        const targetPos = boat.position.clone();
        targetPos.y = 40;

        const dir = new THREE.Vector3().subVectors(targetPos, zep.position);
        const distToBoat = dir.length();
        dir.normalize();

        const targetRotY = Math.atan2(dir.x, dir.z) - Math.PI;
        zep.rotation.y += (targetRotY - zep.rotation.y) * cutsceneDt * 2.5;

        if (distToBoat > 15) {
          zep.position.add(dir.clone().multiplyScalar(cutsceneDt * 20.0));
        }

        if (distToBoat < 45.0 && !window.monologState.airshipCaughtPlayer) {
          window.monologState.airshipCaughtPlayer = true;

          window.playSoundEffect(window.airshipAttackAudio);
          window.isCutscenePlaying = true;

// === [#TUTOR.04.39.00] START | name: startAbduction | lines: ~32 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: startAbduction.
          const startAbduction = () => {
            window.airshipAbductionActive = true;
            window.airshipAbductionProgress = 0;
            window.airshipOriginalY = zep.position.y;

            if (window.foundZeppelinLadder) {
              window.airshipLadderMesh = window.foundZeppelinLadder;
            } else if (!window.airshipLadderMesh) {
              const ladderGroup = new THREE.Group();
              const ropeMat = new THREE.MeshStandardMaterial({ color: 0x3d2516, roughness: 0.9 });
              const stepMat = new THREE.MeshStandardMaterial({ color: 0x6b4c2a, roughness: 0.7 });

              const r1 = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 18, 6), ropeMat);
              r1.position.set(-0.8, -9, 0);
              const r2 = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 18, 6), ropeMat);
              r2.position.set(0.8, -9, 0);
              ladderGroup.add(r1); ladderGroup.add(r2);

              for (let s = 0; s < 12; s++) {
                const step = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.12, 0.2), stepMat);
                step.position.set(0, -1.5 * s - 0.5, 0);
                ladderGroup.add(step);
              }
              zep.add(ladderGroup);
              window.airshipLadderMesh = ladderGroup;
            }

            if (window.airshipLadderMesh) {
              window.airshipLadderMesh.visible = true;
              window.airshipLadderMesh.scale.set(1, 0.01, 1);
            }
          };
// === [#TUTOR.04.39.00] END ===

          window.showPopUp((window.gamePopups && window.gamePopups.airship_catch) || "UTOLÉRTEK! Kérdezni fognak. Ha jól válaszolsz, megússzuk, \nde ha hibázol, elveszik a hártyáinkat.");
          startAbduction();
        }
      }
    }
  }

  if (window.airshipAbductionActive && window.foundZeppelin && boat) {
    const zep = window.foundZeppelin;
    window.airshipAbductionProgress += cutsceneDt * 0.48;
    const p = Math.min(window.airshipAbductionProgress, 1.0);

    const p_zep = Math.min(p / 0.6, 1.0);
    const p_ladder = Math.max(0, (p - 0.6) / 0.4);

    zep.position.x = THREE.MathUtils.lerp(zep.position.x, boat.position.x, cutsceneDt * 3.0);
    zep.position.z = THREE.MathUtils.lerp(zep.position.z, boat.position.z, cutsceneDt * 3.0);
    zep.position.y = THREE.MathUtils.lerp(window.airshipOriginalY || 40.0, 22.0, p_zep);

    if (window.airshipLadderMesh) {
      window.airshipLadderMesh.visible = true;
      const scaleY = THREE.MathUtils.lerp(0.01, 1.15, p_ladder);
      window.airshipLadderMesh.scale.set(1, scaleY, 1);
    }

    if (p >= 1.0) {
      if (window.currentZozoTTSAudio && !window.currentZozoTTSAudio.paused && !window.currentZozoTTSAudio.ended) return;
      window.airshipAbductionActive = false;
      console.log("✈️ Léghajó elkapás: kötéllétra leért, TUTORZEP kvíz indítása...");
      if (window.quizManager) {
        window.quizManager.openQuiz('TUTORZEP', function (isCorrect) {
          console.log("✈️ TUTORZEP kvíz lezárva. Helyes:", isCorrect);
          if (window.isFishingMode) {
            if (isCorrect) {
              // Tutorial paritás: helyes válasszal a rakomány biztonságban megmarad a fedélzeten
            } else {
              window.carriedMembranes = 0;
              if (typeof window.updateTopBarCounts === 'function') window.updateTopBarCounts();
            }
          }
          if (window.airshipLadderMesh) window.airshipLadderMesh.visible = false;
          window.isCutscenePlaying = false;
          window.resetAirshipChase();
        });
      } else {
        console.warn("⚠️ window.quizManager nem elérhető a léghajó elkapásakor!");
        if (window.airshipLadderMesh) window.airshipLadderMesh.visible = false;
        window.isCutscenePlaying = false;
        window.resetAirshipChase();
      }
    }
  }

  // ─── 🏆 EoG: PONT A TRIGGER: Kizárólag a kijelölt A pont (-100, 0, 550) 200 méteres körzetében ugrik fel az 1. monológ ───
  const isEogReady = (window.eogState === 'EMPTIED' || (window.storedMembranes >= 30 && window.eogState !== 'DONE' && window.eogState !== 'CINEMATIC' && window.eogState !== 'VIDEO'));
  if (isEogReady && !window.eogTriggerA) {
    const dxA = boat.position.x - EoG_POINT_A.x;
    const dzA = boat.position.z - EoG_POINT_A.z;
    if (dxA * dxA + dzA * dzA < 40000) { // r = 200m körzet az A pont (-100, 0, 550) körül
      window.eogTriggerA = true;
      window.eogState = 'POINT_A_SHOWN';
      if (!window.chestModel) spawnEogTreasureChest(scene, EoG_POINT_C);
      showZozoEogMonolog(
        (window._currentEogKey = 'eog_pointA', window.eogMonologues.pointA || 'Te, Patkány! Gyanúsan üres a víz...\nNézzük meg, hogy mi a helyzet az öböl szájánál!'),
        function () {
          window.isCutscenePlaying = false;
          window.eogState = 'POINT_A_SHOWN';
        }
      );
    }
  }

  if ((window.eogState === 'POINT_A_SHOWN' || window.eogState === 'EMPTIED' || window.eogState === 'CHEST_VISIBLE') && !window.eogTriggerB) {
    const dxB = boat.position.x - EoG_POINT_B.x;
    const dzB = boat.position.z - EoG_POINT_B.z;
    if (dxB * dxB + dzB * dzB < 3600) {
      window.eogTriggerB = true;
// === [#TUTOR.04.3A.00] START | name: showBMonolog | lines: ~9 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: showBMonolog.
      function showBMonolog() {
        showZozoEogMonolog(
          (window._currentEogKey = 'eog_pointB', window.eogMonologues.pointB || 'Mi az ott a parton?'),
          function () {
            window.isCutscenePlaying = false;
            window.eogState = 'POINT_B_SHOWN';
          }
        );
      }
// === [#TUTOR.04.3A.00] END ===
      if (!window.eogTriggerA) {
        window.eogTriggerA = true;
        window.eogState = 'POINT_A_SHOWN';
        if (!window.chestModel) spawnEogTreasureChest(scene, EoG_POINT_C);
        showZozoEogMonolog(
          window.eogMonologues.pointA || 'Te, Patkány! Gyanúsan üres a víz...',
          function () { showBMonolog(); }
        );
      } else {
        showBMonolog();
      }
    }
  }

  if (!window.eogTriggerChest && window.chestModel && window.chestModel !== 'LOADING') {
    const distToChest = Math.hypot(boat.position.x - window.chestModel.position.x, boat.position.z - window.chestModel.position.z);
    if (distToChest < EoG_CHEST_TRIGGER_DIST) {
      window.eogTriggerChest = true;
      window.eogState = 'CHEST_FOUND';
      window.isWindActive = false; // Szél leállítása az EoG felületekhez
      window.chestModel.visible = false;
      if (window.chestGlowDisc) window.chestGlowDisc.visible = false;
      try { playEogFanfare(); } catch (e) { }
      showZozoEogMonolog(
        (window._currentEogKey = 'eog_chestFound', window.eogMonologues.chestFound || 'Most én viszem vissza a csónakot a mólóra.\nNem hagyom, hogy ezt elszúrd nekem!'),
        function () {
          startEogCinematic(scene, boat);
        }
      );
    }
  }

  if (window.eogState === 'CINEMATIC' && window.eogCinematicPath && cutsceneDt > 0) {
    if (window.isEogPathEditorActive) {
      window.eogCinematicStartTime += (rawDt * 1000);
    }
    const elapsed = (performance.now() - window.eogCinematicStartTime) / 1000;
    const DURATION = 20.0; // Egyenletes, felgyorsított visszatérési sebesség (nem lassul be a kanyarokban)
    const t = Math.min(elapsed / DURATION, 1.0);

    const pos = window.eogCinematicPath.getPointAt(t);
    if (pos) {
      boat.position.copy(pos);
      boat.position.y = 0;
    }

    const tangent = window.eogCinematicPath.getTangentAt(t);
    if (tangent) {
      const targetAngle = Math.atan2(-tangent.x, -tangent.z);
      boat.rotation.y = targetAngle;
    }
    window.setOrb(0, 15.0, 26.00);

    if (t >= 1.0 && !window.eogPierArrived) {
      window.eogPierArrived = true;
      if (typeof showChestAtPier === 'function') showChestAtPier(scene);
    }
  }

  if (water && water.material.uniforms['time']) {
    water.material.uniforms['time'].value += cutsceneDt;
  }

  const SPEED = 50, TURN = 75;
  let targetMv = 0, tr = 0;
  if (!window.isCutscenePlaying && !window.isBayExitModalOpen) {
    if (keys.KeyW || keys.ArrowUp) targetMv = 1;
    if (keys.KeyS || keys.ArrowDown) targetMv = -1;
    if (keys.KeyA || keys.ArrowLeft) tr = -1;
    if (keys.KeyD || keys.ArrowRight) tr = 1;
  }

  window.currentMv = window.currentMv || 0;
  if (dt > 0) {
    if (window._rockRespawnLock) {
      window.currentMv = 0;
      targetMv = 0;
    }

    if (targetMv > 0) {
      if (window.currentMv < 0.20) window.currentMv = 0.20;
      window.currentMv = Math.min(1, window.currentMv + dt * 0.75);
    } else if (targetMv < 0) {
      if (window.currentMv > -0.20) window.currentMv = -0.20;
      window.currentMv = Math.max(-1, window.currentMv - dt * 0.75);
    } else {
      if (window.currentMv > 0) window.currentMv = Math.max(0, window.currentMv - dt * 8.0);
      else if (window.currentMv < 0) window.currentMv = Math.min(0, window.currentMv + dt * 8.0);
    }
  }
  let mv = window.currentMv;

  _prevPos.copy(boat.position);
  const prevRot = boat.rotation.y;

  let windForceX = 0, windForceZ = 0;
  if (window.isWindActive && !window.isCutscenePlaying) {
    let pierDist = 999.0;
    if (window.homePos) {
      const dxP = boat.position.x - window.homePos.x;
      const dzP = boat.position.z - window.homePos.z;
      pierDist = Math.sqrt(dxP * dxP + dzP * dzP);
    }

    let effectiveWindForce = 0.5;
    if (pierDist <= 60.0) {
      effectiveWindForce = 0; // A móló közvetlen 60 méteres körzetében nincs szélsodrás!
    } else if (pierDist <= 120.0) {
      effectiveWindForce = 0.015 + Math.random() * 0.025; // 0.015 – 0.040 (Extrém gyenge szellő)
    } else if (pierDist <= 500.0) {
      effectiveWindForce = 0.10 + Math.random() * 0.50; // 0.10 – 0.60 (Belső öböl)
    } else if (pierDist <= 700.0) {
      effectiveWindForce = 0.30 + Math.random() * 0.50; // 0.30 – 0.80 (Öböl kijárata)
    } else {
      effectiveWindForce = 0.10 + Math.random() * 0.90; // 0.10 – 1.00 (Nyílt tenger)
    }

    let wX = Math.sin(window.currentWindAngle);
    let wZ = Math.cos(window.currentWindAngle);

    // Móló 120m-es körzetében a móló felé irányuló szélvektor teljesen nulla:
    if (pierDist <= 60.0) {
      wX = 0;
      wZ = 0;
    } else if (pierDist <= 120.0 && window.homePos) {
      const toPierX = window.homePos.x - boat.position.x;
      const toPierZ = window.homePos.z - boat.position.z;
      const toPierLen = Math.hypot(toPierX, toPierZ);
      if (toPierLen > 0.1) {
        const dirX = toPierX / toPierLen;
        const dirZ = toPierZ / toPierLen;
        const dot = wX * dirX + wZ * dirZ;
        if (dot > 0) {
          // Levonjuk a móló felé mutató komponenst
          wX -= dot * dirX;
          wZ -= dot * dirZ;
        }
      }
    }

    _fwd.set(0, 0, -1).applyQuaternion(boat.quaternion);

    const windAlignment = _fwd.x * wX + _fwd.z * wZ;

    windForceX = wX * effectiveWindForce * 18.0;
    windForceZ = wZ * effectiveWindForce * 18.0;

    if (mv > 0) {
      mv *= (1.0 + windAlignment * effectiveWindForce * 0.45);
    }
  }

  if (window.sailRig) {
    let targetSailAngle = 0;

    if (window.isWindActive && typeof effectiveWindForce === 'number' && effectiveWindForce > 0.05) {
      let relativeWind = (window.currentWindAngle - boat.rotation.y) % (Math.PI * 2);

      while (relativeWind < -Math.PI) relativeWind += Math.PI * 2;
      while (relativeWind > Math.PI) relativeWind -= Math.PI * 2;

      const MAX_SAIL_ANGLE = 70 * (Math.PI / 180);
      targetSailAngle = THREE.MathUtils.clamp(-relativeWind * 0.5, -MAX_SAIL_ANGLE, MAX_SAIL_ANGLE);
    } else {
      targetSailAngle = 0; // Szélcsend a mólónál: vitorla semleges középállásban
    }

    window.sailRig.rotation.y = THREE.MathUtils.lerp(
      window.sailRig.rotation.y,
      targetSailAngle,
      cutsceneDt * 3.5
    );
  }

  if (Math.abs(mv) > 0.01 && dt > 0) {
    const dir = mv < 0 ? -1 : 1;
    boat.rotation.y -= tr * dir * (TURN * Math.PI / 180) * dt;
    let spd = SPEED;
    if (mv < 0) spd = 30.0;
    _fwd.set(0, 0, -1).applyQuaternion(boat.quaternion);
    _step.copy(_fwd).multiplyScalar(mv * spd * dt);
    boat.position.add(_step);
  } else if (Math.abs(tr) > 0.01 && dt > 0) {
    boat.rotation.y -= tr * (TURN * Math.PI / 180) * dt;
  }

  // --- VÍZFELSZÍNI RINGÁS ÉS DŐLÉS (Csónak lágy, lassított fel-le lebegése) ---
  const waveTime = t * 1.2;
  if (window.isSinking) {
    const elapsedSink = Math.max(0, (performance.now() - (window.sinkingStartTime || performance.now())) / 1000);
    const TILT_DURATION = 1.2;
    const PLUNGE_DURATION = 3.0;

    const baseRotY = window._sinkingBaseRotY !== undefined ? window._sinkingBaseRotY : boat.rotation.y;
    boat.rotation.order = 'YXZ';

    if (elapsedSink < TILT_DURATION) {
      // 1. Fázis: A hajó hátradől a tatja felé (orr felemelkedik, tat leér a vízbe ~70 fokban)
      const pTilt = elapsedSink / TILT_DURATION;
      const targetPitch = 1.22; // ~70 fokos hátradőlés a tat felé
      boat.rotation.y = baseRotY;
      boat.rotation.x = pTilt * targetPitch;
      boat.rotation.z = 0;
      boat.position.y = THREE.MathUtils.lerp(0, -1.8, pTilt);
    } else {
      // 2. Fázis: 3 másodperc alatt egyenletes sebességgel, egyenes irányban lefelé elsüllyed
      const pPlunge = Math.min((elapsedSink - TILT_DURATION) / PLUNGE_DURATION, 1.0);
      boat.rotation.y = baseRotY;
      boat.rotation.x = 1.22;
      boat.rotation.z = 0;
      boat.position.y = -1.8 - (pPlunge * 20.0); // Egyenletes lineáris süllyedés 20 méter mélyre
    }
  } else {
    boat.rotation.order = 'XYZ';
    boat.position.y = Math.sin(waveTime * 1.8) * 0.18 + Math.cos(waveTime * 0.9) * 0.08;
    boat.rotation.z = Math.sin(waveTime * 0.75) * 0.035 + (tr * -0.04);
    boat.rotation.x = Math.cos(waveTime * 0.9) * 0.02 + (mv * 0.02);
  }

  if (window.isWindActive && !window.isCutscenePlaying && dt > 0) {
    boat.position.x += windForceX * dt;
    boat.position.z += windForceZ * dt;
  }

  let collisionDetected = false;
  let hitHeight = 0;
  let hitType = null;

  let closestHitPoint = null;
  let minCollisionDist = 999.0;

  // 1. Raycast whiskers - 360 fokos intelligens ütközésvizsgálat
  // Ha csak egyhelyben forgunk (mv == 0), nem blokkoljuk a szabad kormányzást!
  const isTranslating = Math.abs(mv) > 0.01;
  const isDrifting = window.isWindActive && !window.isCutscenePlaying && (Math.abs(windForceX) > 0.01 || Math.abs(windForceZ) > 0.01);

  if ((isTranslating || isDrifting) && borderMeshes.length > 0 && window.eogState !== 'CINEMATIC') {
    _center.set(boat.position.x, 0.3, boat.position.z);

    laserLines.forEach((lItem) => {
      const id = lItem.w.id;
      let shouldCheck = false;

      if (mv > 0.01) {
        if (id === 'FORWARD' || id === 'FRONT_LEFT' || id === 'FRONT_RIGHT' || id === 'SIDE_LEFT' || id === 'SIDE_RIGHT') shouldCheck = true;
      } else if (mv < -0.01) {
        if (id === 'BACKWARD' || id === 'BACK_LEFT' || id === 'BACK_RIGHT' || id === 'SIDE_LEFT' || id === 'SIDE_RIGHT') shouldCheck = true;
      } else if (isDrifting) {
        shouldCheck = true;
      }

      if (!shouldCheck) {
        lItem.mat.color.setHex(0x00ffcc);
        return;
      }

      _rayDir.set(0, 0, -1);
      _rayDir.applyAxisAngle(_upAxis, lItem.w.angle);
      _rayDir.applyQuaternion(boat.quaternion).normalize();

      const maxDetectDist = lItem.w.dist + (Math.abs(mv) * 2.0);

      _sharedRaycaster.set(_center, _rayDir);
      const intersects = _sharedRaycaster.intersectObjects(borderMeshes, false);

      if (intersects.length > 0 && intersects[0].distance < maxDetectDist) {
        collisionDetected = true;
        lItem.mat.color.setHex(0xff2200);
        
        if (intersects[0].distance < minCollisionDist) {
          minCollisionDist = intersects[0].distance;
          closestHitPoint = intersects[0].point;
        }

        const hitObj = intersects[0].object;
        let detected = (hitObj.userData && hitObj.userData.obstacleType) || 'beach';
        const hitName = (hitObj.name || '').toLowerCase();
        if (hitName.includes('dock') || hitName.includes('pier') || hitName.includes('molo') || hitName.includes('móló') || hitName.includes('homepoint') || hitName.includes('shanty') || hitName.startsWith('sm_bld_')) {
          detected = 'homepoint';
        } else if (hitName.includes('rock') || hitName.includes('stone') || hitName.includes('cliff') || hitName.includes('reef')) {
          detected = 'rock';
        } else if (hitName.includes('beach') || hitName.includes('sand') || hitName.includes('shore') || hitName.includes('part') || hitName.includes('terrain')) {
          detected = 'beach';
        }

        // Ha a móló közvetlen 22 méteres körzetében vagyunk és nem sziklát találtunk, az mindig a Bázis/Móló (homepoint)
        if (window.homePos && Math.hypot(boat.position.x - window.homePos.x, boat.position.z - window.homePos.z) < 22.0) {
          if (detected !== 'rock') {
            detected = 'homepoint';
          }
        }

        hitType = detected;
      } else {
        lItem.mat.color.setHex(0x00ffcc);
      }
    });
  }

  if (!hitType) hitType = 'beach';

  window._lastHitType = window._lastHitType || null;

  if (collisionDetected) {
    // --- VISSZALÉPÉS AZ ELŐZŐ POZÍCIÓRA & MEGÁLLÁS (Forgás szabadon működik!) ---
    window.currentMv = 0;
    mv = 0;
    windForceX = 0;
    windForceZ = 0;
    boat.position.copy(_prevPos);

    // Kiszabadító vektor (Repulsion): Ha sziklához vagy parthoz értünk, ellökjük a csónakot a nyílt víz felé
    if (closestHitPoint) {
      const pushAway = new THREE.Vector3(boat.position.x - closestHitPoint.x, 0, boat.position.z - closestHitPoint.z);
      if (pushAway.lengthSq() > 0.001) {
        pushAway.normalize();
        boat.position.add(pushAway.multiplyScalar(2.0));
      }
    }

    if (hitType !== window._lastHitType) {
      window._lastHitType = hitType;
      if (hitType === 'rock') { /* Hang az új HP logikában van kezelve */ }
      else if (hitType === 'beach') window.playSoundEffect(window.beachTouchAudio);
      else if (hitType === 'homepoint') window.playSoundEffect(window.homepointTouchAudio);
      else if (hitType === 'out_of_range') window.playSoundEffect(window.outOfRangeAudio);
    }

    if (hitType === 'beach') {
      if (!window._beachPopupCooldown) {
        window._beachPopupCooldown = true;
        window.showPopUp((window.gamePopups && window.gamePopups.beach) || "A partra nem kéne felfutni");
        setTimeout(() => {
          window._beachPopupCooldown = false;
        }, 2000);
      }
    }
    else if (hitType === 'out_of_range') {
      if (typeof window.showBayExitDialog === 'function') {
        window.showBayExitDialog();
      }
    }

    else if (hitType === 'rock') {
      if (!window._rockCrashCooldown) {
        window._rockCrashCooldown = true;

        window.boatDurability = Math.max(0, (window.boatDurability !== undefined ? window.boatDurability : 10) - 1);
        const tbDur = document.getElementById('tb-durability-count');
        if (tbDur) tbDur.innerText = window.boatDurability;

        const crashOverlay = document.getElementById('crash-overlay');

        if (window.boatDurability === 0) {
          // 1. Először a nagy robaj / törés hang (Big_crash.mp3)
          if (typeof window.playSoundEffect === 'function') window.playSoundEffect(window.bigCrashAudio || window.crashRockAudio);
          
          if (crashOverlay) {
            const crashSpan = crashOverlay.querySelector('span');
            if (crashSpan) {
              crashSpan.innerText = (typeof window.getReefCrashText === 'function') ? window.getReefCrashText() : '💥 Zátonyra futottál!';
            }
            crashOverlay.style.background = 'rgba(255, 0, 0, 0.7)';
            crashOverlay.style.display = 'flex';
            setTimeout(() => { crashOverlay.style.display = 'none'; }, 1000);
          }
          
          window.showPopUp((window.gamePopups && window.gamePopups.boat_totalcar) || "Elsüllyedtél. Belőled nem lesz hajós.");
          window.isCutscenePlaying = true; // Letiltja az irányítást
          window.isSinking = true;
          window.sinkingStartTime = performance.now();
          window._sinkingBaseRotY = boat.rotation.y;

          // 2. Pontosan akkor indul a süllyedés hang (Boat_Sinking.mp3), amikor a hajó elérte a maximális dőlésszöget és elindul lefelé (1.2 mp-nél)
          setTimeout(() => {
            if (typeof window.playSoundEffect === 'function') window.playSoundEffect(window.boatSinkingAudio);
          }, 1200);
          
          // 3. 4.2 másodperc után (1.2s hátradőlés + 3.0s lemerülés) visszatérés a Main Menübe
          setTimeout(() => {
            // Mentett állás törlése, hogy a "Játék Folytatása" gomb inaktívvá váljon
            try {
              localStorage.removeItem('ebook_pirates_game_state');
              localStorage.removeItem('saved_boat_transform');
              localStorage.removeItem('ebp_tutorial_save');
              document.cookie = "ebook_pirates_game_state=; path=/; expires=Thu, 01 Jan 1970 00:00:00 UTC;";
            } catch (e) { }

            if (typeof window.exitFishingGame === 'function') {
              window.exitFishingGame('DESTROYED');
            } else {
              window.location.href = 'https://krystohans.github.io/ebookpirates_site/';
            }
          }, 4300);

        } else {
          // Csónak ütközés fa ropogás hangeffekt (Boat_Crash.mp3)
          if (typeof window.playSoundEffect === 'function') window.playSoundEffect(window.crashRockAudio);
          
          // Enyhe piros villanás a sima ütközésnél
          if (crashOverlay) {
            const crashSpan = crashOverlay.querySelector('span');
            if (crashSpan) {
              crashSpan.innerText = (typeof window.getReefCrashText === 'function') ? window.getReefCrashText() : '💥 Zátonyra futottál!';
            }
            crashOverlay.style.background = 'rgba(255, 0, 0, 0.3)';
            crashOverlay.style.display = 'flex';
            setTimeout(() => { 
                crashOverlay.style.display = 'none'; 
                crashOverlay.style.background = 'rgba(255, 0, 0, 0.7)'; // Visszaállítjuk az eredetit a megsemmisüléshez
            }, 300);
          }

          if (window.boatDurability < 2) {
            if (typeof window.showMhTowPanel === 'function') { window.showMhTowPanel(); }
          } else {
            window.showPopUp((window.getBoatDamageText ? window.getBoatDamageText(window.boatDurability) : `⚠️ A hajótest megrongálódott! Életerő: ${window.boatDurability} / 10.`));
          }
          
          // Nincs teleportálás, de adunk 1 másodperc védelmet a következő ütközésig
          setTimeout(() => {
            window._rockCrashCooldown = false;
          }, 1000);
        }
      }
    }
  } else {
    window._lastHitType = null;

    if (window._homeEmptyEntered === true && boat && boat.position && window.homePos) {
      const dxH = boat.position.x - window.homePos.x;
      const dzH = boat.position.z - window.homePos.z;
      if (dxH * dxH + dzH * dzH > 900.0) { // 30 méternél messzebb távolodva old fel a móló elhagyásakor
        window._homeEmptyEntered = false;
      }
    }
  }

  // DINAMIKUS HÁRTYA UTÁNTÖLTÉS - Csak az 1. hártya sikeres mólós leadása UTÁN indulhat el!
  if (typeof window.spawnHartyaWave === 'function' && window.activeMembranes && window.firstMembraneDelivered === true && window.eogState === 'NONE') {
    if (window.activeMembranes.length < 10 && window.totalSpawnedCount < 60) {
      // Csak 5 másodpercenként próbáljon utántölteni
      if (!window._lastDynamicSpawnTime || performance.now() - window._lastDynamicSpawnTime > 5000) {
        window._lastDynamicSpawnTime = performance.now();
        const spawnAmount = Math.min(10 - window.activeMembranes.length, 60 - window.totalSpawnedCount);
        if (spawnAmount > 0) {
          window.spawnHartyaWave(spawnAmount, 'boat');
        }
      }
    }
  }

  if (Math.abs(mv) > 0.01 && dt > 0) {
    // Bal oldali duplázott sávok (Left side double streams)
    const wakeMatL1 = getPooledWakeMaterial();
    const wakeL1 = new THREE.Mesh(wakeGeo, wakeMatL1);
    wakeL1.rotation.x = -Math.PI / 2;
    wakeL1.rotation.z = boat.rotation.y;
    const offsetL1 = new THREE.Vector3(-0.35, 0, 3.0).applyQuaternion(boat.quaternion);
    wakeL1.position.copy(boat.position).add(offsetL1);
    wakeL1.position.y = 0.15;
    wakeL1.userData.vel = new THREE.Vector3(-0.18, 0, 0.38).applyQuaternion(boat.quaternion);
    scene.add(wakeL1);
    boatWakes.push(wakeL1);

    const wakeMatL2 = getPooledWakeMaterial();
    const wakeL2 = new THREE.Mesh(wakeGeo, wakeMatL2);
    wakeL2.rotation.x = -Math.PI / 2;
    wakeL2.rotation.z = boat.rotation.y;
    const offsetL2 = new THREE.Vector3(-0.75, 0, 3.2).applyQuaternion(boat.quaternion);
    wakeL2.position.copy(boat.position).add(offsetL2);
    wakeL2.position.y = 0.15;
    wakeL2.userData.vel = new THREE.Vector3(-0.32, 0, 0.42).applyQuaternion(boat.quaternion);
    scene.add(wakeL2);
    boatWakes.push(wakeL2);

    // Jobb oldali duplázott sávok (Right side double streams)
    const wakeMatR1 = getPooledWakeMaterial();
    const wakeR1 = new THREE.Mesh(wakeGeo, wakeMatR1);
    wakeR1.rotation.x = -Math.PI / 2;
    wakeR1.rotation.z = boat.rotation.y;
    const offsetR1 = new THREE.Vector3(0.35, 0, 3.0).applyQuaternion(boat.quaternion);
    wakeR1.position.copy(boat.position).add(offsetR1);
    wakeR1.position.y = 0.15;
    wakeR1.userData.vel = new THREE.Vector3(0.18, 0, 0.38).applyQuaternion(boat.quaternion);
    scene.add(wakeR1);
    boatWakes.push(wakeR1);

    const wakeMatR2 = getPooledWakeMaterial();
    const wakeR2 = new THREE.Mesh(wakeGeo, wakeMatR2);
    wakeR2.rotation.x = -Math.PI / 2;
    wakeR2.rotation.z = boat.rotation.y;
    const offsetR2 = new THREE.Vector3(0.75, 0, 3.2).applyQuaternion(boat.quaternion);
    wakeR2.position.copy(boat.position).add(offsetR2);
    wakeR2.position.y = 0.15;
    wakeR2.userData.vel = new THREE.Vector3(0.32, 0, 0.42).applyQuaternion(boat.quaternion);
    scene.add(wakeR2);
    boatWakes.push(wakeR2);
  }

  const timeScale = cutsceneDt * 60;
  for (let i = boatWakes.length - 1; i >= 0; i--) {
    let w = boatWakes[i];
    if (w.userData.vel) {
      w.position.addScaledVector(w.userData.vel, cutsceneDt);
    }
    w.scale.x += 0.015 * timeScale;
    w.scale.y += 0.015 * timeScale;
    w.material.opacity -= 0.008 * timeScale;

    if (w.material.opacity <= 0) {
      scene.remove(w);
      boatWakes.splice(i, 1);
    }
  }

  if (window.tempOrbitEnabled && window.tempOrbit) {
    window.tempOrbit.update();
  } else {
    if (window.recordingModeActive && window.foundZeppelin) {
      const elapsedSec = (performance.now() - window.recordingStartTime) / 1000.0;
      window.recordingAngle = (elapsedSec / 45.0) * (Math.PI * 2);

      cam.position.set(
        window.foundZeppelin.position.x + 70 * Math.sin(window.recordingAngle),
        window.foundZeppelin.position.y + 55,
        window.foundZeppelin.position.z + 70 * Math.cos(window.recordingAngle)
      );
      cam.lookAt(new THREE.Vector3(window.foundZeppelin.position.x, window.foundZeppelin.position.y + 15, window.foundZeppelin.position.z));
      if (window.cinematicLight) {
        window.cinematicLight.position.copy(cam.position);
        window.cinematicLight.lookAt(window.foundZeppelin.position);
      }
    }
    else if (window.isEogPathEditorActive) {
      // OrbitControls handles it
    }
    else if (window.eogState === 'CINEMATIC' && window.homePos) {
      const bX = (boat && boat.position) ? boat.position.x : 5.0;
      const bY = 0.0; // Stabil rögzített magasság a kamerának, hogy CSAK a csónak mozduljon fel-le!
      const bZ = (boat && boat.position) ? boat.position.z : -94.0;
      const bRotY = (boat && boat.rotation) ? boat.rotation.y : 0;
      const totalH = bRotY + (orbH * Math.PI / 180);
      const vR = orbV * Math.PI / 180;
      cam.position.set(
        bX + orbDist * Math.sin(totalH) * Math.cos(vR),
        bY + orbDist * Math.sin(vR) + LOOK_OFFSET_Y,
        bZ + orbDist * Math.cos(totalH) * Math.cos(vR)
      );
      cam.lookAt(new THREE.Vector3(bX, bY + LOOK_OFFSET_Y, bZ));
    }
    else if (window.airshipAbductionActive && window.foundZeppelin) {
      const bX = (boat && boat.position) ? boat.position.x : 5.0;
      const bZ = (boat && boat.position) ? boat.position.z : -94.0;
      cam.position.set(bX - 35, 18, bZ + 35);
      cam.lookAt(new THREE.Vector3(bX, 15, bZ));
    }
    else if (window.airshipAscentStarted && !window.airshipAscentDone && window.foundZeppelin && window.foundZeppelin.position) {
      cam.position.set(-374, 25, 1347);
      cam.lookAt(window.foundZeppelin.position);
    }
    else {
      const bX = (boat && boat.position) ? boat.position.x : 5.0;
      const bY = 0.0; // Stabil rögzített magasság a kamerának, hogy CSAK a csónak mozduljon fel-le!
      const bZ = (boat && boat.position) ? boat.position.z : -94.0;
      const bRotY = (boat && boat.rotation) ? boat.rotation.y : 0;
      const totalH = bRotY + (orbH * Math.PI / 180);
      const vR = orbV * Math.PI / 180;
      
      const targetPos = new THREE.Vector3(bX, bY + LOOK_OFFSET_Y, bZ);
      const dirX = Math.sin(totalH) * Math.cos(vR);
      const dirY = Math.sin(vR);
      const dirZ = Math.cos(totalH) * Math.cos(vR);
      const camRayDir = new THREE.Vector3(dirX, dirY, dirZ).normalize();

      let effectiveDist = orbDist;
      if (borderMeshes && borderMeshes.length > 0) {
        _sharedRaycaster.set(targetPos, camRayDir);
        const camHits = _sharedRaycaster.intersectObjects(borderMeshes, false);
        if (camHits.length > 0 && camHits[0].distance < orbDist) {
          // Ha szikla vagy akadály van a kamera és a csónak között, előrehúzzuk a kamerát a szikla elé
          effectiveDist = Math.max(2.2, camHits[0].distance - 0.7);
        }
      }

      cam.position.set(
        bX + dirX * effectiveDist,
        bY + dirY * effectiveDist + LOOK_OFFSET_Y,
        bZ + dirZ * effectiveDist
      );
      cam.lookAt(targetPos);
    }
  }

  water.position.x = cam.position.x;
  water.position.z = cam.position.z;
  if (window.skyDome) {
    window.skyDome.position.x = cam.position.x;
    window.skyDome.position.z = cam.position.z;
    if (window.starField) window.starField.rotation.y += 0.00012;
  }

  renderer.render(scene, cam);
}
frame();

// === [#TUTOR.04.3B.00] START | name: showZozoEogMonolog | lines: ~43 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: showZozoEogMonolog.
window.showZozoEogMonolog = function (text, onCloseCallback, eogKey) {
  window._currentEogKey = eogKey ? (eogKey.startsWith('eog_') ? eogKey : ('eog_' + eogKey)) : null;
  const dialog = document.getElementById('eog-compact-dialog');
  const textEl = document.getElementById('eog-dialog-text');
  if (!dialog || !textEl) return;

  textEl.innerText = text;
  if (typeof window.fitDialogueText === 'function') window.fitDialogueText(textEl, 26, 14);
  dialog.style.display = 'block';
  window.isCutscenePlaying = true;
  window.currentMv = 0;

  let isClosed = false;

// === [#TUTOR.04.3C.00] START | name: closeEogDialog | lines: ~10 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: closeEogDialog.
  function closeEogDialog() {
    if (isClosed) return;
    isClosed = true;
    dialog.style.display = 'none';
    window.isCutscenePlaying = false;
    document.removeEventListener('keydown', onKey);
    dialog.removeEventListener('click', onClick);
    document.removeEventListener('click', onClick);
    if (typeof onCloseCallback === 'function') onCloseCallback();
  }
// === [#TUTOR.04.3C.00] END ===

// === [#TUTOR.04.3D.00] START | name: onKey | lines: ~8 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: onKey.
  function onKey(e) {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.tagName === 'SELECT') return;
    // Kizárólag Space vagy Enter gombra záródjon be, mint a standard játéknarratív monológok!
    if (e.code === 'Space' || e.key === ' ' || e.code === 'Enter') {
      e.preventDefault();
      closeEogDialog();
    }
  }
// === [#TUTOR.04.3D.00] END ===

// === [#TUTOR.04.3E.00] START | name: onClick | lines: ~4 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: onClick.
  function onClick(e) {
    if (e && e.target && e.target.closest && e.target.closest('.zozo-read-aloud-btn')) return;
    if (e && e.stopPropagation) e.stopPropagation();
    if (typeof window.stopZozoTTS === 'function') window.stopZozoTTS();
    closeEogDialog();
  }
// === [#TUTOR.04.3E.00] END ===

// === [#TUTOR.04.3B.00] END ===
  setTimeout(function () {
    document.addEventListener('keydown', onKey);
    dialog.addEventListener('click', onClick);
    document.addEventListener('click', onClick, { once: true });
  }, 300);
};

// === [#TUTOR.04.3F.00] START | name: spawnEogTreasureChest | lines: ~41 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: spawnEogTreasureChest.
function spawnEogTreasureChest(sceneRef, point) {
  window.chestModel = 'LOADING'; // Prevent multiple calls while loading
  const loader = new GLTFLoader();
  loader.load(window.getAssetUrl('models/pirates_assets/SM_Prop_Chest_Treasure_01.glb'), function (gltf) {
    window.chestModel = gltf.scene;
    window.chestModel.position.set(point.x, 0.75, point.z);
    window.chestModel.scale.set(250, 250, 250);
    sceneRef.add(window.chestModel);

    window.chestModel.traverse(function (child) {
      if (child.isMesh && child.material) {
        child.material.emissive = new THREE.Color(0x332200);
        child.material.roughness = 0.3;
        child.material.metalness = 0.8;
        child.material.needsUpdate = true;
      }
    });

    const discGeom = new THREE.CylinderGeometry(3.5, 3.5, 0.4, 32);
    const pillarGeom = new THREE.CylinderGeometry(2.5, 4.0, 100, 16);
    const pillarMat = new THREE.MeshBasicMaterial({ color: 0xffea00, transparent: true, opacity: 0.75, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
    const pillar = new THREE.Mesh(pillarGeom, pillarMat);
    pillar.position.set(0, 50.0, 0);
    const corePillar = new THREE.Mesh(new THREE.CylinderGeometry(1.0, 1.6, 100, 16), new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.92, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }));
    corePillar.position.set(0, 50.0, 0);
    const discMat = new THREE.MeshBasicMaterial({ color: 0xffaa00, transparent: true, opacity: 0.7 });
    const glowDisc = new THREE.Mesh(discGeom, discMat);
    glowDisc.position.set(point.x, 1.85, point.z);
    glowDisc.add(pillar);
    glowDisc.add(corePillar);
    sceneRef.add(glowDisc);

    const chestLight = new THREE.PointLight(0xffdd44, 4500.0, 500);
    chestLight.position.set(0, 0.5, 0);
    glowDisc.add(chestLight);
    window.chestGlowLight = chestLight;
    window.chestGlowDisc = glowDisc;
    window.eogState = 'CHEST_VISIBLE';
  }, undefined, function (err) {
    const fallback = new THREE.Mesh(
      new THREE.BoxGeometry(2, 1.5, 1.2),
      new THREE.MeshStandardMaterial({ color: 0xc8a040, roughness: 0.4, metalness: 0.7 })
    );
    fallback.position.set(point.x, 0.75, point.z);
    sceneRef.add(fallback);
    window.chestModel = fallback;
    window.eogState = 'CHEST_VISIBLE';
  });
}
// === [#TUTOR.04.3F.00] END ===

// === [#TUTOR.04.40.00] START | name: startEogCinematic | lines: ~68 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: startEogCinematic.
function startEogCinematic(sceneRef, boatRef) {
  window.eogState = 'CINEMATIC';
  window.isWindActive = false; // Szél teljes leállítása

  // Fények felkapcsolása a mólón és a faházakon
  dockLanternLights.forEach(light => { light.intensity = 180.0; });
  if (window.lantern1Light) window.lantern1Light.intensity = 180.0;
  if (window.lantern2Light) window.lantern2Light.intensity = 180.0;

  if (window.smallLantern1Light) window.smallLantern1Light.intensity = 140.0;
  if (window.smallLantern2Light) window.smallLantern2Light.intensity = 140.0;
  if (window.mainRockLanternLight) window.mainRockLanternLight.intensity = 3500.0;

  shantyLights.forEach(light => {
    if (light.userData && (light.userData.name === 'sm_bld_shanty_preset_08' || light.userData.name === 'sm_bld_shanty_preset_24')) {
      light.intensity = 350.0;
    }
  });

  // --- Shanty belső ablakfény (emissive glow) ---
  if (window.fullTrack) {
    window.fullTrack.traverse(function (child) {
      if (!child.isMesh) return;
      const cName = (child.name || '').toLowerCase();
      if (cName.includes('shanty') || cName.includes('house') || cName.startsWith('sm_bld_')) {
        if (child.material) {
          const mat = child.material.clone();
          mat.emissive = new THREE.Color(0xff9933);
          mat.emissiveIntensity = 0.525; // 1.5x-ösére növelve (0.35 -> 0.525)
          mat.needsUpdate = true;
          child.material = mat;
          child.userData.eogEmissiveApplied = true;
        }
      }
    });
  }

  window.eogPierArrived = false;
  window.eogLidAngle = 0;
  window.eogCinematicStartTime = performance.now();

  const startPos = boatRef.position.clone();

  // Pontos felhasználói útvonal koordináták
  window.eogCinematicWaypoints = [
    { x: -433.0, y: 0, z: 1207.3 },
    { x: -477.9, y: 0, z: 1075.3 },
    { x: -492.7, y: 0, z: 1038.3 },
    { x: -479.3, y: 0, z: 969.0 },
    { x: -440.6, y: 0, z: 750.6 },
    { x: -429.3, y: 0, z: 735.9 },
    { x: -373.7, y: 0, z: 618.8 },
    { x: -189.4, y: 0, z: 553.2 },
    { x: -106.7, y: 0, z: 391.3 },
    { x: -62.6, y: 0, z: 271.3 },
    { x: -37.5, y: 0, z: 120.4 },
    { x: -20.1, y: 0, z: 48.4 },
    { x: 14.4, y: 0, z: -79.4 },
    { x: 4.6, y: 0, z: -94.7 }
  ];

  const pts = [startPos];
  window.eogCinematicWaypoints.forEach(wp => {
    pts.push(new THREE.Vector3(wp.x, wp.y, wp.z));
  });

  window.eogCinematicPath = new THREE.CatmullRomCurve3(pts);
}
