// === [#TUTOR.04.5C.00] START | name: loadWarshipForFishing | lines: ~37 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: loadWarshipForFishing.
window.loadWarshipForFishing = function () {
  if (window.warshipMesh) {
    window.warshipMesh.visible = true;
    return;
  }
  const loader = new GLTFLoader();
  loader.load('https://storage.googleapis.com/kalozsziget-assets/models/SM_Veh_Boat_Warship_01_Hull.glb', function (gltf) {
    const warshipModel = gltf.scene;
    warshipModel.scale.set(60.0, 60.0, 60.0);
    warshipModel.updateMatrixWorld(true);

    const box = new THREE.Box3().setFromObject(warshipModel);
    const size = box.getSize(new THREE.Vector3());
    const center = box.getCenter(new THREE.Vector3());

    warshipModel.position.x -= center.x;
    warshipModel.position.z -= center.z;
    warshipModel.position.y += size.y * 0.35;

    warshipModel.traverse(function (node) {
      if (node.isMesh) {
        node.castShadow = false;
        node.receiveShadow = false;
        node.frustumCulled = true;
      }
    });

    const warshipGroup = new THREE.Group();
    warshipGroup.position.set(-450, 0, 1650);
    warshipGroup.add(warshipModel);
    scene.add(warshipGroup);
    window.warshipMesh = warshipGroup;
    console.log("⚓ Csatahajó (Warship) sikeresen betöltve a nyílt vizekre!");
  }, undefined, function (err) {
    console.warn("Csatahajó modell betöltési figyelmeztetés:", err);
  });
};
// === [#TUTOR.04.5C.00] END ===

// === [#TUTOR.04.5D.00] START | name: spawnFishingMembranes | lines: ~20 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: spawnFishingMembranes.
window.spawnFishingMembranes = function () {
  const active = (window.activeMembranes || []).filter(m => m && m.visible).length;
  const needed = Math.max(0, 8 - active);
  if (needed > 0) {
    if (typeof window.spawnHartyaWave === 'function') {
      window.spawnHartyaWave(needed, 'fishing');
    } else if (typeof getPooledMembrane === 'function' || typeof window.getPooledMembrane === 'function') {
      const getMembrane = typeof getPooledMembrane === 'function' ? getPooledMembrane : window.getPooledMembrane;
      for (let i = 0; i < needed; i++) {
        const pt = WATER_BAY_POINTS[Math.floor(Math.random() * WATER_BAY_POINTS.length)];
        if (pt) {
          const m = getMembrane();
          if (m) {
            m.position.set(pt.x + (Math.random() - 0.5) * 10, 0.1, pt.z + (Math.random() - 0.5) * 10);
            m.userData.baseY = 0.1;
            m.userData.collected = false;
            m.userData.inUse = true;
            m.visible = true;
            if (m.userData.light) m.userData.light.intensity = 1.2;
            if (!window.activeMembranes.includes(m)) window.activeMembranes.push(m);
          }
        }
      }
    }
  }
};
// === [#TUTOR.04.5D.00] END ===

// === [#TUTOR.04.5E.00] START | name: triggerFishingQuiz | lines: ~16 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: triggerFishingQuiz.
// === [#TUTOR.04.5D.50] START | name: showBayExitDialog | lines: ~65 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: Öböl kijárat megerősítő felugró ablak és döntéskezelés (Igen / Tovább halászok).
window.showBayExitDialog = function (isManual) {
  const overlay = document.getElementById('bay-exit-confirm-overlay');
  if (!overlay) return;
  if (overlay.style.display === 'flex' || (window._bayExitCooldown && Date.now() < window._bayExitCooldown)) {
    return;
  }

  window.isBayExitModalOpen = true;
  window.currentMv = 0;
  if (typeof mv !== 'undefined') mv = 0;

  const curLang = (window.getGameLanguage ? window.getGameLanguage() : (window.currentLanguage || localStorage.getItem('ebook_pirates_language') || localStorage.getItem('siteLang') || 'hu')).toLowerCase();
  const dict = (window.UI_TRANSLATIONS && (window.UI_TRANSLATIONS[curLang] || window.UI_TRANSLATIONS.hu)) || {};

  const titleEl = document.getElementById('bay-exit-title');
  const btnYes = document.getElementById('btn-bay-exit-yes');
  const btnNo = document.getElementById('btn-bay-exit-no');

  if (titleEl) titleEl.innerText = dict.bayExitTitle || "Elhajózol Hebokba?";
  if (btnYes) btnYes.innerText = dict.bayExitYes || "Igen";
  if (btnNo) btnNo.innerText = dict.bayExitNo || "Tovább halászok";

  overlay.style.display = 'flex';

  if (btnNo) {
    btnNo.onclick = function (e) {
      if (e) e.stopPropagation();
      overlay.style.display = 'none';
      window.isBayExitModalOpen = false;
      window._bayExitCooldown = Date.now() + 2000;

      // Enyhén visszatoljuk a csónakot az öböl belseje felé (18 méterrel), de a fal ott marad!
      if (!isManual && typeof boat !== 'undefined' && boat && boat.position) {
        const bayCenter = new THREE.Vector3(-300, 0, 600);
        const pushDir = new THREE.Vector3().subVectors(bayCenter, boat.position).normalize();
        boat.position.add(pushDir.multiplyScalar(18.0));
      }
    };
  }

  if (btnYes) {
    btnYes.onclick = function (e) {
      if (e) e.stopPropagation();
      overlay.style.display = 'none';
      window.isBayExitModalOpen = false;

      // Hártyák mentése: carried -> stored
      if (window.carriedMembranes > 0) {
        window.storedMembranes = (window.storedMembranes || 0) + window.carriedMembranes;
        window.carriedMembranes = 0;
        if (typeof window.updateTopBarCounts === 'function') window.updateTopBarCounts();
      }

      if (typeof window.playHebokDepartureVideo === 'function') {
        window.playHebokDepartureVideo();
      } else {
        const targetUrl = 'https://krystohans.github.io/ebookpirates_site/';
        if (window.top && window.top !== window) window.top.location.href = targetUrl;
        else window.location.href = targetUrl;
      }
    };
  }
};
// === [#TUTOR.04.5D.50] END ===

window.triggerFishingQuiz = function () {
  if (window.quizManager) {
    window.quizManager.openQuiz('FISHING', function (isCorrect, wasDoubleOrNothing) {
      if (wasDoubleOrNothing) {
        if (isCorrect) {
          window.carriedMembranes = (window.carriedMembranes > 0) ? (window.carriedMembranes * 2) : 2;
        } else {
          window.carriedMembranes = 0;
        }
      } else {
        if (isCorrect) {
          window.carriedMembranes = (window.carriedMembranes || 0) + 1;
        }
      }
      if (typeof window.updateTopBarCounts === 'function') window.updateTopBarCounts();
      if (typeof window.changeWindForNextMembrane === 'function') window.changeWindForNextMembrane();
      setTimeout(function () {
        if (typeof window.spawnFishingMembranes === 'function') window.spawnFishingMembranes();
      }, 1500);
    });
  } else {
    window.carriedMembranes = (window.carriedMembranes || 0) + 1;
    if (typeof window.updateTopBarCounts === 'function') window.updateTopBarCounts();
  }
};
// === [#TUTOR.04.5E.00] END ===

// === [#TUTOR.04.5F.00] START | name: exitFishingGame | lines: ~57 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: exitFishingGame.
window.exitFishingGame = function (type) {
  const exitType = type || 'NORMAL';
  let targetPage = (exitType === 'DESTROYED') ? 'kikoto_oldal' : 'fedelzet_oldal';

  if (exitType !== 'DESTROYED' && window.carriedMembranes > 0) {
    window.storedMembranes = (window.storedMembranes || 0) + window.carriedMembranes;
    window.carriedMembranes = 0;
    if (typeof window.updateTopBarCounts === 'function') window.updateTopBarCounts();
  }

  // Backend mentés
  if (window.parent && window.parent !== window && typeof window.parent.callBackend === 'function') {
    const uParams = new URLSearchParams(window.location.search);
    const sId = uParams.get('shipId') || '';
    if (window.storedMembranes > 0) {
      window.parent.callBackend('saveHartyaScore', [window.storedMembranes]);
    }
    window.parent.callBackend('saveBoatDurability', [window.boatDurability || 10, sId]);
  }

// === [#TUTOR.04.60.00] START | name: doExitNavigation | lines: ~19 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: doExitNavigation.
  function doExitNavigation() {
    if (window.parent && window.parent !== window) {
      window.parent.postMessage({
        source: 'threejs-minigame',
        status: 'COMPLETED',
        gameType: 'FISHING',
        exitType: exitType,
        targetPage: targetPage,
        score: window.storedMembranes || 0,
        durability: window.boatDurability || 10
      }, '*');
    } else {
      const targetUrl = 'https://krystohans.github.io/ebookpirates_site/';
      if (window.top && window.top !== window) window.top.location.href = targetUrl;
      else window.location.href = targetUrl;
    }
  }
// === [#TUTOR.04.60.00] END ===

  // Normál kilépésnél (gomb vagy nyílt tengeri aktív zóna) lejátsszuk a terkeputazas01.mp4 videót
  if (exitType === 'NORMAL') {
    const vidOverlay = document.getElementById('hebok-departure-video-overlay');
    const vid = document.getElementById('hebok-departure-video');
    if (vidOverlay && vid) {
      if (window.bgMusicAudio) { window.bgMusicAudio.muted = true; window.bgMusicAudio.pause(); }
      if (window.ambSoundAudio) { window.ambSoundAudio.pause(); }
      vid.muted = !!window.isMusicMuted;
      vidOverlay.style.display = 'flex';
      vid.currentTime = 0;
      vid.play().catch(() => {});
      let exited = false;
// === [#TUTOR.04.61.00] START | name: finishVid | lines: ~6 ===
// @subsystem: TUTOR.03_HartyaVadaszat
// @summary: 3D Hártyavadászat funkció: finishVid.
      const finishVid = function () {
        if (exited) return;
        exited = true;
        vidOverlay.style.display = 'none';
        doExitNavigation();
      };
// === [#TUTOR.04.61.00] END ===
      vid.onended = finishVid;
      setTimeout(finishVid, 6500); // Biztonsági fallback időzítő
      return;
    }
// === [#TUTOR.04.5F.00] END ===
  }

  setTimeout(doExitNavigation, 500);
};


